#include <jyppx/liuding/vision/tasks/open_vocabulary.hpp>
#include <jyppx/liuding/vision/tasks/workflow/binding.hpp>
#include <torch/torch.h>
namespace jyppx::liuding::vision::tasks {
training::BatchMapper make_prompt_image_mapper(PromptInputOptions o){if(o.classes<1||o.classes>1024)throw InvalidArgument("Prompt input class bound invalid");return[o=std::move(o)](const data::BatchEnvelope& e){auto b=data::image::image_batch_from_value(e.value);auto empty=torch::empty({0},b.images.options());if(o.prompt_free)return nn::Invocation{{b.images,empty,empty},{}};
  std::vector<Tensor> prompts,masks;std::string label_space;
  for(const auto& item:b.items){if(!item.task_payload)throw InvalidArgument("Open-vocabulary input requires explicit typed prompts");const auto& p=*item.task_payload;
    if(p.label_space_id.empty()||(!label_space.empty()&&p.label_space_id!=label_space))throw CompatibilityError("Prompt label-space identity differs within batch");label_space=p.label_space_id;
    if(o.visual){if(!p.visual_prompts.defined())throw InvalidArgument("Visual prompt profile needs class/xyxy boxes");auto boxes=p.visual_prompts.to(torch::kCPU,torch::kFloat32);auto canvas=torch::zeros({o.classes,b.images.size(2)/8,b.images.size(3)/8});for(std::int64_t i=0;i<boxes.size(0);++i){auto category=boxes[i][0].item<double>();if(category!=std::floor(category)||category<0||category>=o.classes)throw InvalidArgument("Visual prompt category outside vocabulary");auto x1=static_cast<std::int64_t>(std::floor(boxes[i][1].item<double>()/8)),y1=static_cast<std::int64_t>(std::floor(boxes[i][2].item<double>()/8));auto x2=static_cast<std::int64_t>(std::ceil(boxes[i][3].item<double>()/8)),y2=static_cast<std::int64_t>(std::ceil(boxes[i][4].item<double>()/8));x1=std::clamp(x1,0LL,canvas.size(2));x2=std::clamp(x2,0LL,canvas.size(2));y1=std::clamp(y1,0LL,canvas.size(1));y2=std::clamp(y2,0LL,canvas.size(1));if(x2>x1&&y2>y1)canvas[static_cast<std::int64_t>(category)].slice(0,y1,y2).slice(1,x1,x2).fill_(1);}masks.push_back(canvas);}
    else{if(p.text_encoder_id.empty()||(!o.text_encoder_identity.empty()&&p.text_encoder_id!=o.text_encoder_identity))throw CompatibilityError("Prompt text-encoder identity mismatch");if(p.prompt_embeddings.defined()){if(p.prompt_embeddings.sizes()!=torch::IntArrayRef({o.classes,512}))throw InvalidArgument("Prompt embedding vocabulary shape mismatch");prompts.push_back(p.prompt_embeddings);}
      else{if(!o.encode_text||p.text_prompts.size()!=o.classes)throw InvalidArgument("Raw text needs matching native tokenizer/encoder assets and complete vocabulary");prompts.push_back(o.encode_text(p.text_prompts));}}}
  return nn::Invocation{{b.images,o.visual?empty:torch::stack(prompts).to(b.images.options()),o.visual?torch::stack(masks).to(b.images.options()):empty},{}};};}
training::StepFunction make_prompt_step(YoloTaskOptions task,bool prompt_free){return[task,prompt_free](const training::StepInput& in){if(!in.target||!in.target->isTuple())throw InvalidArgument("Prompt training requires rich task targets");const auto& t=in.target->toTupleRef().elements();if(t.size()!=4)throw InvalidArgument("Prompt target tuple arity mismatch");TaskTargets targets{t[0].toTensor(),t[1].toTensor(),t[2].toTensor(),t[3].toTensor()};auto images=in.invocation.positional[0].toTensor();auto prediction=in.model.invoke(in.invocation);auto raw=raw_tensors(prediction.value);if(raw.size()!=3)throw InvalidArgument("Prompt output arity mismatch");std::vector<Tensor> supervised{raw[0]};if(task.task==TaskKind::instance_segment)supervised.push_back(raw[1]);auto loss=yolo_task_loss(supervised,targets,{images.size(2),images.size(3)},task,in.context.epoch);
  if(prompt_free){auto detection=raw[0].slice(1,0,64+task.detection.num_classes);auto decoded=decode_yolo_detection(detection,{images.size(2),images.size(3)},task.detection);auto assignment=assign_yolo_targets(decoded,targets.boxes,task.detection);loss.total=loss.total+torch::nn::functional::binary_cross_entropy_with_logits(raw[2].squeeze(1),assignment.foreground.to(raw[2].scalar_type()));}
  training::StepOutput out;out.loss=in.context.phase==training::StepPhase::validation?loss.total/images.size(0):loss.total;out.sample_count=images.size(0);out.prediction=std::move(prediction);return out;};}
}
